) AS (
  VALUES 
    (210::BIGINT, 'El mejor profe que me he topado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2026-07-25T00:00:00+00:00'::TIMESTAMPTZ, '5f093d0ff4cef48374a389c9a446a619732341f13424eabb7cdb1c4e2a561a53'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (210::BIGINT, 'De los mejores profes que tuve en el TEC es increíble la capacidad del profe para motivar al estudiante, también la confianza y cercanía que hace sentir a uno como estudiante hace que uno nunca deje el curso botado por más mal que le vaya, una teja de profe, pero mejor persona aún, la ???? absoluta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, '723c4a655bb9b3e9d8bb5fb207d0059e1813fafd96a40f57d7b35a2a6e4ba1c5'::TEXT, ARRAY[630]::BIGINT[]),
    (210::BIGINT, 'El mejor profesor de física. Explica clarísimo y las veces que usted necesite, da mucha ayuda con centros antes de los exámenes y por telegram. Califica justo y es una teja de persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'e636b63cbefa3e7f3f0f83faeb65ed8be71ac85392dac21d7cc094cef182fe3a'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (210::BIGINT, 'El mejor profe!! Si lo tiene de opción no dude y matricule con él. Explica muy bien y califica justo. Hizo clases extra antes de exámenes para hacer ejercicios y resolver dudas, ayuda mucho. También es todo vacilón, una teja el Jerry.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'ad8db08421ea9af5b3d42478d6fae3953b7a951e52928dc09ee59de642511262'::TEXT, ARRAY[604]::BIGINT[]),
    (210::BIGINT, 'Excelente profesor. Da la materia necesaria y clara para el examen. Hace ejercicios de todo tipo en clase. Siempre dispuesto a contestar dudas dentro y fuera de clase. Hace varios centros antes del examen con ejercicios muy útiles. Evaluación llevadera. Recomendado para cualquier curso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '3dda4e66652cdb19db2f68cab82096839f7d94845eddb4b7dbbf5dffa6b633e1'::TEXT, ARRAY[604]::BIGINT[]),
    (210::BIGINT, 'CRACK. El mejor profe de Física de la Escuela. Siempre preocupado por el estudiante y buscando la forma de colaborar. Si está con un profe malo en teoría, puede llegar a entender algunos temas con lo que explica en lab. RECOMENDADO ES POCO!!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'ccc3c78f787f78d39d6c7dd0b8a5091cfb488b62fc12dd86060da7ab2bed9cbb'::TEXT, ARRAY[631]::BIGINT[]),
    (210::BIGINT, 'Es de esos profes que velan por el estudiante, hace centros para explicar, está muy atento a dudas ...etc La clase es muy entretenida y provechosa porque explica super bien. No dude en matricular con él, eso sí, repase un poco de Dragon ball'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, '8a390c0467c036e04e291de3db2c03375c0c853d301c215fdb6f17a0275009eb'::TEXT, ARRAY[604]::BIGINT[]),
    (210::BIGINT, 'Es un gran profesor y una teja de persona. Da muchos ejemplos y centros antes de los exámenes. Sus clases son divertidas. Matricule 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'e4330ba4a074970a0e4b3d28e6100ed6c7cb01a80ca5dca848736f3530b753c5'::TEXT, ARRAY[604]::BIGINT[]),
    (210::BIGINT, 'El profe se esfuerza porque uno logre entender los temas con ejemplos cotidianos, lo cual facilita mucho el curso. Califica justo, quitando pocos puntos por errores que se arrastren en los incisos de las preguntas. Su clase tiene un buen ambiente.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'bf0fa67a3887a1b525bf822c92a7f3d12cf965ac4558339c8ff3efbc3963fc85'::TEXT, ARRAY[604]::BIGINT[]),
    (210::BIGINT, 'Física pasó de ser una clase que tenía fama de ser dura y que la gente reprobaba, a una clase interesante, educativa y sobre todo divertida. El profesor explica súper bien, obvio hay que prestarle atención, brinda apoyo y hace clases extra para dudas. Lo mejor de todo, es fan de Dragon Ball'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, '2e765a8f75d4529e11debd9d02844aadb7f8611494c8ac4e2b3dc3233efc6db7'::TEXT, ARRAY[604]::BIGINT[]),
    (210::BIGINT, 'El profe es un 100, califica regular, es muy comprensivo y hace sus clases dinámicas y entretenidas, ayuda bastante, hace clases extra para hacer ejercicios para el examen y no deja muchas tareas. Excelente profesor, matriculé con él sin pensarlo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-11-14T00:00:00+00:00'::TIMESTAMPTZ, '9c3b7f5bf756819f764670d4c8565f0436288b8c52e7e548dc8cf453cc9ec08a'::TEXT, ARRAY[604]::BIGINT[]),
    (210::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'a6f2a538b96da1065b6bf445c118011e3c9bf0c3bbc90251bd3716d571a5ee8b'::TEXT, ARRAY[604]::BIGINT[]),
    (210::BIGINT, 'En resumidas cuentas, matricule con él. El profe es una teja, siempre dispuesto a ayudar, da más tiempo para las entregas, explica bien, califica normal y hace la clase muy amena.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'e350a6e3807fb92d5c58bf8fe5ad275b4280c7b1e3586c0fedf59b38b6aecfb3'::TEXT, ARRAY[607]::BIGINT[]),
    (210::BIGINT, 'Excelente profe, hace que el curso no sea tan aburrido. Brinda bastante ayuda si usted la pide. Lo recomiendo bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '65dcff793625ad755983b6289747743958652a0aeff1e224e5c9917da6b3a4d4'::TEXT, ARRAY[607]::BIGINT[]),
    (210::BIGINT, 'Muy buenas clases'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '1802efd7d6784ee7241a85ef5bfff57f587f8fe941dc2676dd5489986be93183'::TEXT, ARRAY[922]::BIGINT[]),
    (210::BIGINT, 'El curso es demasiado aburrido pero el profe es super ocurrente y gracioso. Ayuda con las fechas de entrega y apoya mucho con las tareas, quices.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2022-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'ae6c23e808f2ad0b8c6703f8bfac924dedf77dd9e6a6ad04a70eff51803bc60d'::TEXT, ARRAY[922]::BIGINT[]),
    (210::BIGINT, 'Muy buen profe, súper recomendado se preocupa por el estudiante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-13T00:00:00+00:00'::TIMESTAMPTZ, '2bfc4dc0e8d42ec6141a7bb8b8de07e5c4f4995e5e120c1a55464c295a491bd0'::TEXT, ARRAY[922]::BIGINT[]),
    (210::BIGINT, 'Lo amo, es demasiado crack xd. Sabe muchísimo, se preocupa y ayuda al estudiante, aclara las dudas en cualquier momento, flexible con fechas de entrega y hace sus clases muy graciosas y entretenidas. Lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-19T00:00:00+00:00'::TIMESTAMPTZ, '030810be78b884c50b4b60d744a559463f6a8914fd9568f6c564503a0037e681'::TEXT, ARRAY[631]::BIGINT[]),
    (210::BIGINT, 'Excelente profesora. Explica muy bien y de vez en cuando dice una que otra broma que ayuda a que la clase no sea tan pesada. Si un tiene alguna duda el las responde muy rápido. Si tienen posibilidad de matricular con él, háganlo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, '22aa0da2363c7e3a191832d065e773a1fecab228633d126e267c7a970312d0be'::TEXT, ARRAY[604]::BIGINT[]),
    (210::BIGINT, 'Buen profes, es entretenido llevar clases con él, es comprensivo y brinda apoyo a los estudiantes. Si lleva con él, le pone ganas y muestra interés fijo pasa el curso'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ed6577b097163b9bce52523b3e8bead55f2c10d4994428f95f642cd4e7dde465'::TEXT, ARRAY[604]::BIGINT[]),
    (210::BIGINT, 'Muy buen profe, es muy comprensivo y ayuda bastante, además hace que sus clases sean entretenidas y menos tediosas :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4b7ae830ef2b1c5b248f5f0d256c3a596f87214e5c763aae45780158474ffa57'::TEXT, ARRAY[631]::BIGINT[]),
    (210::BIGINT, 'No se cuestione matricular con él, Yerry es lo mejor, lo único malo o aburrido de sus clases son por la materia que tiene que dar y las evaluaciones que tiene que aplicar. De lo mejor que tiene la universidad. Si va a matricular con él vaya descargandose Warzone.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'b63a42056bc8ee2f7814d2b76b2c6d0323ccb573451de8a50faa6a65b9e53f2e'::TEXT, ARRAY[631]::BIGINT[]),
    (210::BIGINT, 'El profe es el mejor en serio, yo ya estaba que mandaba física por el caño pero Jerry hacía que valiera la pena. Súper cómico, hace que la clase sea interesante. Responde dudas en un balazo. Trata de ayudar lo más que pueda a los estudiantes y en serio es súper buena nota. El mejor profe de física'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'feefb2a27201804a1fd89472a6ce80ada58239650ffe79c49a8303b7f2c8001d'::TEXT, ARRAY[604]::BIGINT[]),
    (210::BIGINT, 'Lo amo, el mejor profe de la escuela de física. Explica súper bien y medio hace que la clase no sea tan tediosa. A veces resuelve los ejercicios de la tarea o ayuda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'b32252f1f20b31e7905adedc2180f04e1ce46c3216b2cb969086afc9b10d3f8d'::TEXT, ARRAY[922]::BIGINT[]),
    (210::BIGINT, 'Explica muy bien la materia y está atento a aclarar las dudas de los estudiantes. Resuelve varios ejercicios en clase, lo cual ayuda al estudiante a comprender la materia. Además es muy cómico, lo cual ayuda a mantener la atención durante la clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-02-10T00:00:00+00:00'::TIMESTAMPTZ, '459828d8ec846c13eda92336e612ccb44c90b457a55a5bf2e96519b2de4ec2fb'::TEXT, ARRAY[922]::BIGINT[]),
    (210::BIGINT, 'Es el mejor profe de física, no lo duden y matriculen con él. Explica bien, es gracioso y está atento a cualquier duda que tengas en los trabajos. En verdad, una teja de profe!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'b0b9a2f4829e79e51cc085d0ac1cf82666c8c146fafea28b669e66e4501fe2f9'::TEXT, ARRAY[922]::BIGINT[]),
    (210::BIGINT, 'Es un excelente profe, muy divertido y se esfuerza porque todos entiendan. Si tienen la oportunidad de llevar un curso con él, no lo duden de verdad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '6a9b20590cbc6c9d37329bccdb9a60285323c6000a6c5f48f8e743f58b22a806'::TEXT, ARRAY[607]::BIGINT[]),
    (210::BIGINT, 'Es sin duda alguna uno de los mejores profes. Explica todo súper, es demasiado divertido y una excelente persona. No piense y matricule con él de fijo, es pura calidad. 11/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-10-28T00:00:00+00:00'::TIMESTAMPTZ, '351aa43616d07fc8a08cc15b45f4c9acc5ef90096b0f299a8c6719e9907795d5'::TEXT, ARRAY[607]::BIGINT[]),
    (210::BIGINT, 'Demasiado saico, te amo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2021-10-21T00:00:00+00:00'::TIMESTAMPTZ, 'efb124f18e2d8d22eb4bae16d22c56d3255d331d58afeb76dba1986e6ccb884b'::TEXT, ARRAY[922]::BIGINT[]),
    (210::BIGINT, 'El mejor profe de física del mundo. Creo que es un profe nuevo, pero definitivamente es uno de los mejores profes que me ha dado en la U. Es suuper claro, super cómico, super pura vida y realmente enseña. No dude en meter algo de física con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-09-14T00:00:00+00:00'::TIMESTAMPTZ, '7f66f3f898b4c4413d188063ecb5c1c045d8d6ad7001dbbf2fdbad1f2556de31'::TEXT, ARRAY[607]::BIGINT[]),
    (210::BIGINT, 'se preocupa por hacer la clase llevadera, de los mejores profes de física en lo que se lleva de las clases virtuales, es un profe que dedica el tiempo a aclarar dudas, explicar y resolver ejercicios, con clases sincrónicas 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'f7dcea3cc7194636ce2b2d958a01ed9ec0227d46b4a1163fe01fae843893d1ef'::TEXT, ARRAY[922]::BIGINT[]),
    (210::BIGINT, 'Ojalá la escuela contratara más profesores así, es de los pocos profesores que valen la pena como profesores y como persona, se esforzó para que el curso realmente valiera un crédito, a veces se atrasó con las entregas de trabajos revisados, pero se compensa con el hecho de que es comprensivo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'a785d2ba69a23723bda0314ece1f7f5398c3999d0077366add0700f82d75fbf9'::TEXT, ARRAY[631]::BIGINT[]),
    (210::BIGINT, 'El mejor profe que he tenido en toda la U, master de la comedia y se aprende bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2021-07-07T00:00:00+00:00'::TIMESTAMPTZ, '737ed99769195f7c0940e77c4449301d20c3f1a3b573eedcf43f54318d002a8a'::TEXT, ARRAY[631]::BIGINT[]),
    (210::BIGINT, 'Excelente profe! Explica super claro y hace las clases bien entretenidas. Resuelve muchos ejercicios y da soporte extra para exámenes y tareas. Califica justo, ni más ni menos. :)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'effe49732b54ef2bc68cafb39f01571dcca32054fac0d406c46bfd2ddf7a2fdf'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (210::BIGINT, 'El profe explica muy bien, hace que la clase sea divertida y aclara dudas, muy bueno, califica regular, el curso en si es duro, tiene que estudiar mucho'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c6aecc3a93f70c6414f49a7cfc34fa28d5d2fac56e1c2948ee2f5b093b66e038'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (210::BIGINT, 'Se distrae con facilidad, pero realmente explica excelente y dedica clases enteras a resolver ejercicios como los que aparecerian en tareas o quices. Muy buen profesor la verdad'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '21c45d92ae0e484b7a452b047e48401775cda672879aba943543a0ecf51c9cce'::TEXT, ARRAY[922]::BIGINT[]),
    (210::BIGINT, 'En mi experiencia uno el mejor profesor para llevar laboratorio, se esfuerza porque el curso realmente valga solo un crédito (respecto al consumo de horas/semana) y aún así hacer que con las prácticas se aprenda mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'f7151d8db5524b85d40bf1623b31b02cd523eaa6382cbc007c919bc2a89a4876'::TEXT, ARRAY[631]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
